void SantosLevelerAudioProcessorEditor::HistoryComponent::paint(juce::Graphics&g){auto r=getLocalBounds().toFloat();panel(g,r,7);auto in=r.reduced(10);auto top=in.removeFromTop(38);auto stats=in.removeFromBottom(92);in.removeFromBottom(8);g.setColour(text);g.setFont(juce::FontOptions(14));g.drawText("LIVE RESPONSE",top.toNearestInt(),juce::Justification::centredLeft);const juce::Colour cs[]={cyan,yellow,magenta,green};const char*ns[]={"INPUT","RIDER","PEAK","LEVELER OUT"};auto leg=top.removeFromRight(500);for(int i=0;i<4;++i){auto it=leg.removeFromLeft(leg.getWidth()/(4-i));g.setColour(cs[i]);g.drawLine(it.getX()+4,it.getCentreY(),it.getX()+26,it.getCentreY(),2);g.setFont(juce::FontOptions(10));g.drawText(ns[i],it.withTrimmedLeft(32).toNearestInt(),juce::Justification::centredLeft);}auto chart=in;g.setColour(juce::Colour(0xff03080b));g.fillRoundedRectangle(chart,4);auto plot=chart.reduced(42,14);for(int i=0;i<=5;++i){auto y=plot.getY()+plot.getHeight()*i/5.f;g.setColour(juce::Colour(0xff24313a));g.drawHorizontalLine((int)y,plot.getX(),plot.getRight());g.setColour(muted);g.setFont(juce::FontOptions(9));g.drawText(juce::String(-12*i),(int)chart.getX()+2,(int)y-7,32,14,juce::Justification::centredRight);}auto pts=processor.getHistory().copyLatest(320);if(pts.size()>=2){auto ly=[&](float d){auto n=juce::jlimit(0.f,1.f,(d+60)/60);return plot.getBottom()-n*plot.getHeight();};auto gy=[&](float d){auto n=juce::jlimit(0.f,1.f,(d+12)/24);return plot.getBottom()-n*plot.getHeight();};auto path=[&](auto f){juce::Path p;for(size_t i=0;i<pts.size();++i){auto x=plot.getX()+plot.getWidth()*(float)i/(float)(pts.size()-1),y=f(pts[i]);if(i==0)p.startNewSubPath(x,y);else p.lineTo(x,y);}return p;};auto ip=path([&](const SantosHistoryPoint&p){return ly(p.inputDb);}),op=path([&](const SantosHistoryPoint&p){return ly(p.outputDb);}),rp=path([&](const SantosHistoryPoint&p){return gy(p.riderDb);}),pp=path([&](const SantosHistoryPoint&p){return gy(p.peakDb);});auto fill=[&](juce::Path p){p.lineTo(plot.getRight(),plot.getBottom());p.lineTo(plot.getX(),plot.getBottom());p.closeSubPath();return p;};g.setColour(cyan.withAlpha(.10f));g.fillPath(fill(ip));g.setColour(green.withAlpha(.12f));g.fillPath(fill(op));g.setColour(cyan);g.strokePath(ip,juce::PathStrokeType(1.8f));g.setColour(yellow);g.strokePath(rp,juce::PathStrokeType(2));g.setColour(magenta);g.strokePath(pp,juce::PathStrokeType(1.8f));g.setColour(green);g.strokePath(op,juce::PathStrokeType(1.8f));}const float vs[]={processor.getRiderDb(),pv(processor,"target"),pv(processor,"peakThreshold"),processor.getOutputMeterDb()};const char*sn[]={"RIDER","TARGET","PEAK","LEVELER OUT"};const char*sf[]={" dB"," dB"," dBFS"," dB"};const juce::Colour sc[]={yellow,lime,magenta,green};auto sw=stats.getWidth()/4;for(int i=0;i<4;++i){auto c=stats.withX(stats.getX()+sw*i).withWidth(sw);if(i){g.setColour(border);g.drawVerticalLine((int)c.getX(),c.getY()+14,c.getBottom()-14);}g.setColour(muted);g.setFont(juce::FontOptions(12));g.drawText(sn[i],c.withTrimmedTop(12).withHeight(18).toNearestInt(),juce::Justification::centred);g.setColour(sc[i]);g.setFont(juce::FontOptions(24));g.drawText(juce::String(vs[i],1)+sf[i],c.withTrimmedTop(35).toNearestInt(),juce::Justification::centredTop);}if(processor.hasHostTransport()&&!processor.getTransportPlaying()){g.setColour(juce::Colour(0xaa03070a));g.fillRoundedRectangle(chart,4);g.setColour(text);g.drawText("PAUSED",chart.toNearestInt(),juce::Justification::centred);}}

void SantosLevelerAudioProcessorEditor::MeterComponent::paint(juce::Graphics&g){const auto db=source==Source::input?processor.getInputMeterDb():processor.getOutputMeterDb();auto r=getLocalBounds().toFloat();panel(g,r,7);g.setColour(colour);g.setFont(juce::FontOptions(14));g.drawText(label,0,16,getWidth(),20,juce::Justification::centred);g.setFont(juce::FontOptions(18));g.drawText(juce::String(db,1)+" dBFS",0,42,getWidth(),28,juce::Justification::centred);auto ma=r.withTrimmedTop(82).withTrimmedBottom(38).reduced(14,0);auto scale=ma.removeFromLeft(28);ma.reduce(6,0);auto gap=juce::jmax(5.f,ma.getWidth()*.08f),bw=(ma.getWidth()-gap)/2;auto n=juce::jlimit(0.f,1.f,(db+60)/60);for(int ch=0;ch<2;++ch){auto bar=juce::Rectangle<float>(ma.getX()+(bw+gap)*ch,ma.getY(),bw,ma.getHeight());g.setColour(juce::Colours::black);g.fillRoundedRectangle(bar.expanded(2),3);float gh=2,sh=(bar.getHeight()-gh*33)/34;for(int i=0;i<34;++i){auto ln=(float)(i+1)/34,yy=bar.getBottom()-(i+1)*sh-i*gh;auto seg=juce::Rectangle<float>(bar.getX(),yy,bar.getWidth(),sh);auto led=meterCol(colour,ln);g.setColour(led.withAlpha(ln<=n?.95f:.08f));g.fillRoundedRectangle(seg,1);}}g.setFont(juce::FontOptions(8.5f));for(int i=0;i<=5;++i){auto y=scale.getY()+scale.getHeight()*i/5.f;g.setColour(muted);g.drawText(juce::String(-12*i),scale.withY(y-7).withHeight(14).toNearestInt(),juce::Justification::centredRight);}g.setColour(muted);g.setFont(juce::FontOptions(9));g.drawText("PEAK",0,getHeight()-29,getWidth(),16,juce::Justification::centred);}

void SantosLevelerAudioProcessorEditor::FinalMeterComponent::paint(juce::Graphics&g){auto r=getLocalBounds().toFloat();panel(g,r,6);const auto outDb=processor.getFinalOutputMeterDb();const auto grDb=juce::jlimit(-18.0f,0.0f,processor.getCompressorReductionDb());auto top=r.reduced(8).removeFromTop(52);auto leftTop=top.removeFromLeft(top.getWidth()*.54f);g.setColour(muted);g.setFont(juce::FontOptions(8.5f));g.drawText("FINAL OUT",leftTop.withHeight(13).toNearestInt(),juce::Justification::centred);g.setColour(green);g.setFont(juce::FontOptions(13));g.drawText(juce::String(outDb,1)+" dBFS",leftTop.withTrimmedTop(13).toNearestInt(),juce::Justification::centredTop);g.setColour(muted);g.setFont(juce::FontOptions(8.5f));g.drawText("GR",top.withHeight(13).toNearestInt(),juce::Justification::centred);g.setColour(amber);g.setFont(juce::FontOptions(13));g.drawText(juce::String(grDb,1)+" dB",top.withTrimmedTop(13).toNearestInt(),juce::Justification::centredTop);

auto meterArea=r.withTrimmedTop(63).withTrimmedBottom(52).reduced(7,0);auto outScale=meterArea.removeFromLeft(24);auto grScale=meterArea.removeFromRight(24);meterArea.reduce(3,0);auto gap=juce::jmax(4.f,meterArea.getWidth()*.08f),bw=(meterArea.getWidth()-gap)/2;constexpr int segments=34;const float ledGap=2.f,sh=(meterArea.getHeight()-ledGap*(segments-1))/segments;const auto outNorm=juce::jlimit(0.f,1.f,(outDb+60.0f)/60.0f);const auto grNorm=juce::jlimit(0.f,1.f,-grDb/18.0f);for(int ch=0;ch<2;++ch){auto bar=juce::Rectangle<float>(meterArea.getX()+(bw+gap)*ch,meterArea.getY(),bw,meterArea.getHeight());g.setColour(juce::Colours::black);g.fillRoundedRectangle(bar.expanded(2),3);for(int i=0;i<segments;++i){const auto ln=(float)(i+1)/segments;const auto fromTop=(float)(segments-i)/segments;const auto outOn=ln<=outNorm;const auto grOn=fromTop<=grNorm+0.0001f;auto y=bar.getBottom()-(i+1)*sh-i*ledGap;auto seg=juce::Rectangle<float>(bar.getX(),y,bar.getWidth(),sh);if(grOn)g.setColour(amber.withAlpha(.96f));else if(outOn)g.setColour(meterCol(green,ln).withAlpha(.95f));else g.setColour(juce::Colour(0xff263038).withAlpha(.16f));g.fillRoundedRectangle(seg,1);}}

g.setFont(juce::FontOptions(7.8f));for(int i=0;i<=5;++i){auto y=outScale.getY()+outScale.getHeight()*i/5.f;g.setColour(muted);g.drawText(juce::String(-12*i),outScale.withY(y-6).withHeight(12).toNearestInt(),juce::Justification::centredRight);}for(int i=0;i<=6;++i){auto y=grScale.getY()+grScale.getHeight()*i/6.f;g.setColour(i==0?amber:muted);g.drawText(juce::String(-3*i),grScale.withY(y-6).withHeight(12).toNearestInt(),juce::Justification::centredLeft);}auto tp=processor.getOutputTruePeakDbTP();g.setColour(border.withAlpha(.7f));g.drawHorizontalLine(getHeight()-47,8,getWidth()-8);g.setColour(muted);g.setFont(juce::FontOptions(8));g.drawText("TRUE PEAK",0,getHeight()-43,getWidth(),13,juce::Justification::centred);g.setColour(magenta);g.setFont(juce::FontOptions(12));g.drawText(juce::String(tp,1)+" dBTP",0,getHeight()-29,getWidth(),18,juce::Justification::centred);}

void SantosLevelerAudioProcessorEditor::LoudnessMeterComponent::paint(juce::Graphics&g){auto r=getLocalBounds().toFloat();panel(g,r,6);const auto loudnessBlue=juce::Colour(0xff3f7f98);g.setColour(loudnessBlue.brighter(.25f));g.setFont(juce::FontOptions(12));g.drawText("LOUDNESS",0,10,getWidth(),18,juce::Justification::centred);const float values[]={processor.getShortTermLufs(),processor.getIntegratedLufs()};const char*names[]={"LUFS-S","LUFS-I"};auto header=r.withTrimmedTop(32).withHeight(40);auto half=header.getWidth()*.5f;for(int ch=0;ch<2;++ch){auto cell=juce::Rectangle<float>(header.getX()+half*ch,header.getY(),half,header.getHeight());g.setColour(muted);g.setFont(juce::FontOptions(8));g.drawText(names[ch],cell.withHeight(13).toNearestInt(),juce::Justification::centred);g.setColour(loudnessBlue.brighter(.28f));g.setFont(juce::FontOptions(11));g.drawText(juce::String(values[ch],1),cell.withTrimmedTop(12).toNearestInt(),juce::Justification::centredTop);}auto meterArea=r.withTrimmedTop(72).withTrimmedBottom(20).reduced(10,0);auto scale=meterArea.removeFromRight(24);meterArea.reduce(4,0);auto gap=juce::jmax(5.f,meterArea.getWidth()*.10f);auto bw=(meterArea.getWidth()-gap)*.5f;constexpr int segments=34;const float segGap=2.f,sh=(meterArea.getHeight()-segGap*(segments-1))/segments;for(int ch=0;ch<2;++ch){auto meter=juce::Rectangle<float>(meterArea.getX()+(bw+gap)*ch,meterArea.getY(),bw,meterArea.getHeight());g.setColour(juce::Colours::black);g.fillRoundedRectangle(meter.expanded(2),3);const auto norm=juce::jlimit(0.f,1.f,(values[ch]+24.0f)/12.0f);for(int i=0;i<segments;++i){auto ln=(float)(i+1)/segments;auto y=meter.getBottom()-(i+1)*sh-i*segGap;auto seg=juce::Rectangle<float>(meter.getX(),y,meter.getWidth(),sh);g.setColour(loudnessBlue.withAlpha(ln<=norm?.82f:.07f));g.fillRoundedRectangle(seg,1);}}g.setFont(juce::FontOptions(7.8f));for(int i=0;i<=4;++i){auto y=scale.getY()+scale.getHeight()*i/4.f;g.setColour(muted);g.drawText(juce::String(-12-3*i),scale.withY(y-6).withHeight(12).toNearestInt(),juce::Justification::centredLeft);}}
